import { randomUUID } from 'node:crypto';

/**
 * Document intake rules (`specs/13-security-spec.md` §File upload).
 *
 * - whitelisted MIME types only, and no executable type is ever accepted;
 * - a maximum size;
 * - the object key is generated by the server, never taken from the client,
 *   so a client cannot target or overwrite another object in the private bucket.
 */

/** Whitelist: images and PDF only. Executable/archived types are refused. */
export const ALLOWED_DOCUMENT_CONTENT_TYPES: Record<string, string> = {
  'image/jpeg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'application/pdf': 'pdf',
};

/** 10 MiB. Configurable through `VERIFICATION_DOCUMENT_MAX_BYTES`. */
export const DEFAULT_DOCUMENT_MAX_BYTES = 10 * 1024 * 1024;

/** Dependency-injection token for the configured maximum document size. */
export const VERIFICATION_DOCUMENT_MAX_BYTES = 'VERIFICATION_DOCUMENT_MAX_BYTES';

export function isAllowedDocumentContentType(contentType: string): boolean {
  return ALLOWED_DOCUMENT_CONTENT_TYPES[contentType.trim().toLowerCase()] !== undefined;
}

/**
 * Private-bucket object key for a verification document.
 *
 * The random suffix keeps the key unguessable, so a signed URL is not the only
 * thing protecting an object (`specs/10-privacy-and-minors.md`).
 */
export function buildDocumentKey(caseId: string): string {
  return `verification/${caseId}/${randomUUID()}`;
}

/** Integrity check: `verification_documents.file_hash` is a SHA-256 hex digest. */
export function isSha256Hex(value: string): boolean {
  return /^[0-9a-f]{64}$/i.test(value);
}
